"""Fail-closed application adapter for shared GPU effect/event execution.

This is an external-stimulus evaluator, not the autonomous weapon/burst loop.
No CPU simulation or CPU-produced state is supplied to the GPU.
"""
import copy
import math
import hashlib
import array
import sys
import re
import struct

from portable_backend import execute,execute_batches
from portable_enemy_specs import damage_plan,enemy_buff_plan
from portable_recipient_specs import admitted as recipient_admitted, pack as pack_recipients
from portable_damage_specs import BUFFS,DAMAGE_FAMILIES
from portable_specs import ABI, LIMITS as L, FIELDS as F, check_schema


class UnsupportedPortable(ValueError):
    def __init__(self, message, *, reason=None, operator=None, fields=None):
        self.reason = reason
        self.operator = operator
        self.fields = fields
        super().__init__(message)


class PortableExecutionError(RuntimeError):
    def __init__(self,results,evidence):
        self.results=results
        self.evidence=evidence
        self.statuses=[r['status'] for r in results]
        super().__init__('Portable GPU execution failed closed: '+str(self.statuses))


def double_words(value):
    if isinstance(value, bool) or not isinstance(value, (float,int)) or not math.isfinite(value):
        raise ValueError('Finite numeric input required')
    return list(struct.unpack('<II',struct.pack('<d',value)))


def validate_effect(eff, *, combat=None, world_frame=False):
    target=eff.get('target')
    from portable_projectile_chain_specs import validate as validate_chain
    validate_chain(eff,combat,world_frame)
    from portable_focus_specs import validate as validate_focus
    try:validate_focus(eff,combat=combat,world_frame=world_frame)
    except ValueError as error:raise UnsupportedPortable(str(error),reason='effect') from error
    if target=='allies_below_def' and (combat is None or not world_frame):
        raise UnsupportedPortable('Final-defense recipients require a private combat world',reason='recipient')
    from portable_ally_random_specs import validate as validate_ally_random
    try:validate_ally_random(eff,combat=combat,world_frame=world_frame)
    except ValueError as error:raise UnsupportedPortable(str(error),reason='recipient') from error
    if isinstance(target,str) and (target=='enemies_random' or target.startswith(('enemies_random:','enemies_code:','enemies_lowest_hp_code:'))) and (combat is None or not world_frame):
        raise UnsupportedPortable('Random/code enemy selectors require a private combat world',reason='recipient')
    from portable_named_magnitude_specs import validate as validate_named_magnitude
    try:validate_named_magnitude(eff,combat=combat,world_frame=world_frame)
    except ValueError as error:raise UnsupportedPortable(str(error),reason='effect') from error
    from portable_persona_specs import validate as validate_persona
    try:validate_persona(eff,combat=combat,world_frame=world_frame)
    except ValueError as error:raise UnsupportedPortable(str(error),reason='effect' if eff.get('stat')=='persona_state' else 'recipient') from error
    from portable_base_copy_specs import validate as validate_base_copy,enabled as base_copy
    try:validate_base_copy(eff,combat=combat,world_frame=world_frame)
    except ValueError as error:raise UnsupportedPortable(str(error),reason="effect") from error
    from portable_trigger_reduction_specs import validate as validate_trigger_reduction
    try:validate_trigger_reduction(eff,combat=combat,world_frame=world_frame)
    except ValueError as error:raise UnsupportedPortable(str(error),reason='effect') from error
    from portable_skill_interval_specs import validate as validate_skill_interval
    try:validate_skill_interval(eff,combat=combat,world_frame=world_frame)
    except ValueError as error:raise UnsupportedPortable(str(error),reason='effect') from error
    if isinstance(eff.get('target'),list):
        for target in eff['target']:
            if target!=[]:validate_effect(dict(eff,target=target),combat=combat,world_frame=world_frame)
    from portable_resource_specs import operation as resource_operation,validate as validate_resource
    resource_op=resource_operation(eff);validate_resource(eff)
    from portable_protection_specs import policy as protection_policy
    protection=protection_policy(eff)
    from portable_heal_charge_specs import validate as validate_heal_charge
    try:validate_heal_charge(eff,combat=combat,world_frame=world_frame)
    except ValueError as error:raise UnsupportedPortable(str(error),reason='effect') from error
    from portable_damage_accum_specs import validate as validate_damage_accum
    try:damage_accum=validate_damage_accum(eff,combat=combat,world_frame=world_frame)
    except ValueError as error:raise UnsupportedPortable(str(error),reason='effect') from error
    from periodic_source_specs import specification as source_specification
    source_spec=source_specification(eff)
    from portable_removal_specs import plan as removal_plan
    removal=removal_plan(eff,combat=combat)
    from portable_duration_extend_specs import plan as duration_extend_plan
    extension=duration_extend_plan(eff,combat=combat)
    from portable_stack_specs import plan as stack_plan,operation as stack_operation
    stack=stack_plan(eff,combat=combat)
    from portable_status_specs import cleanse_plan,immunity
    from portable_named_enemy_specs import validate as validate_named_enemy
    validate_named_enemy(eff,combat=combat,world_frame=world_frame)
    cleansing=cleanse_plan(eff,combat=combat)
    if eff.get('type')=='damage' and not isinstance(eff.get('stat',''),str):raise UnsupportedPortable('Damage family must be a string')
    from portable_element_specs import enabled as element_override,validate as validate_element
    validate_element(eff)
    from portable_full_burst_landing_specs import validate as validate_landing
    validate_landing(eff,combat=combat,world_frame=world_frame)
    allowed = {'name','source','type','stat','fixed_value','values','duration','duration_values',
               'target','trigger','note','polarity','favorite','_source_tag','_quant_group','max_ammo_reduction_exclusive','trigger_values','max_stack','max_trigger','tick_interval','tick_start','target_effect','target_skill'}
    if 'land_in_full_burst' in eff:allowed |= {'land_in_full_burst'}
    if eff.get('type')=='damage' and eff.get('stat')=='dot_damage':allowed |= {'ramp_interval','ramp_damage_stack','post_ramp_tick_delay'}
    if element_override(eff):allowed |= {'target_code'}
    if base_copy(eff):allowed |= {'copy_from'}
    if removal is not None:allowed |= {'remove_scope'}
    if protection&255==1:allowed |= {'end_on_shield_consumed'}
    if source_spec:allowed |= {'periodic_source','feather_id','feather_slots','feather_interval_base','feather_interval_step_pct'}
    if resource_op:allowed |= {'gauge_id','gauge_max'}
    from portable_skill_hp_basis_specs import validate as validate_skill_hp_basis
    try:basis=validate_skill_hp_basis(eff,combat=combat,world_frame=world_frame)
    except ValueError as error:raise UnsupportedPortable(str(error),reason='scaling') from error
    if basis.mode:allowed |= {'scaling','scaling_hp_pct'}
    from portable_parent_fixed_specs import validate as validate_parent_fixed
    validate_parent_fixed(eff,combat=combat,world_frame=world_frame)
    from portable_max_ammo_scaling_specs import validate as validate_ammo_scaling
    if validate_ammo_scaling(eff,combat=combat,world_frame=world_frame):allowed |= {'scaling'}
    if eff.get('type')=='damage':
        from portable_parts_skill_specs import validate as validate_parts
        try:
            if validate_parts(eff,combat=combat,world_frame=world_frame):allowed |= {'hits_parts'}
        except ValueError as error:raise UnsupportedPortable(str(error),reason='effect',fields=['hits_parts']) from error
        if world_frame and 'damage_formula' in eff:
            if eff['damage_formula']!='normal_attack':raise UnsupportedPortable('Unknown world skill damage formula')
            allowed |= {'damage_formula'}
        allowed |= {'hit_count_gauge_ref'}
        if eff.get('scaling')=='stack_count' and eff.get('stat','').split(':')[0]!='dot_damage':allowed |= {'scaling','scaling_ref'}
        from portable_reference_specs import hit_reference
        hit_reference(eff)
    if eff.get('type')=='buff' and eff.get('scaling')=='lost_hp_pct':
        if eff.get('stat') not in ('def_pct','atk_pct','dmg_accum_rate_pct'):
            raise UnsupportedPortable('Lost HP scaling requires supported ATK or DEF',reason='scaling')
        if combat is None:raise UnsupportedPortable('Lost HP scaling requires combat-owned health',reason='scaling')
        if eff.get('target','self')!='self' and not damage_accum:raise UnsupportedPortable('Lost HP scaling requires self recipient',reason='recipient')
        allowed |= {'scaling'}
    if eff.get('type')=='buff' and eff.get('scaling')=='stack_count' or eff.get('type')=='damage' and eff.get('stat')=='dot_damage' and eff.get('scaling')=='stack_count' and eff.get('scaling_ref'):
        allowed |= {'scaling','scaling_ref'}
        from portable_reference_specs import scale_reference
        try:scale_reference(eff)
        except ValueError as error:raise UnsupportedPortable(str(error),reason='scaling') from error
    if {'duration_scaling','duration_scaling_ref'} & eff.keys():
        from portable_reference_specs import duration_reference
        try:duration_reference(eff)
        except ValueError as error:raise UnsupportedPortable(str(error),reason='fields',fields=['duration_scaling','duration_scaling_ref']) from error
